#include "instrument_sim.h"
static int wrap_heading(int h){h%=360;return h<0?h+360:h;}
const char *instrument_sim_scenario_name(instrument_sim_scenario_t s){static const char *const n[SIM_SCENARIO_COUNT]={"LEVEL","PITCH +10","PITCH -10","PITCH +20","PITCH -20","BANK LEFT 30","BANK RIGHT 30","BANK LEFT 60","BANK RIGHT 60","PITCH +10 BANK R30","ATTITUDE FAIL","RECOVERY LEVEL","ALT 0","ALT 500","ALT 1000","ALT 2500","ALT 5000","ALT 9500","ALT 10000","ALT SWEEP","ALT FAIL","RECOVERY ALT","HEADING 350-010","HEADING FAIL","ALL FAIL"};return(unsigned)s<SIM_SCENARIO_COUNT?n[s]:"UNKNOWN";}
void instrument_sim_init(instrument_sim_t*s,bool e){s->t=0;s->scenario_t=0;s->enabled=e;s->scenario=SIM_SCENARIO_LEVEL;}
void instrument_sim_set_scenario(instrument_sim_t*s,instrument_sim_scenario_t sc){if((unsigned)sc>=SIM_SCENARIO_COUNT)sc=SIM_SCENARIO_LEVEL;s->scenario=sc;s->scenario_t=0;}
instrument_sim_scenario_t instrument_sim_next_scenario(instrument_sim_t*s){instrument_sim_set_scenario(s,(instrument_sim_scenario_t)((s->scenario+1)%SIM_SCENARIO_COUNT));return s->scenario;}
void instrument_sim_step(instrument_sim_t*s,float dt,instrument_data_t*d){if(!s->enabled)return;s->t+=dt;s->scenario_t+=dt;d->pitch_deg=0;d->roll_deg=0;d->attitude_valid=true;d->altitude_ft=2500;d->altitude_valid=true;d->heading_deg=0;d->heading_valid=true;d->simulated=true;switch(s->scenario){case SIM_SCENARIO_LEVEL:case SIM_SCENARIO_RECOVERY_LEVEL:break;case SIM_SCENARIO_PITCH_UP:d->pitch_deg=10;break;case SIM_SCENARIO_PITCH_DOWN:d->pitch_deg=-10;break;case SIM_SCENARIO_PITCH_UP_20:d->pitch_deg=20;break;case SIM_SCENARIO_PITCH_DOWN_20:d->pitch_deg=-20;break;case SIM_SCENARIO_BANK_LEFT:d->roll_deg=-30;break;case SIM_SCENARIO_BANK_RIGHT:d->roll_deg=30;break;case SIM_SCENARIO_BANK_LEFT_60:d->roll_deg=-60;break;case SIM_SCENARIO_BANK_RIGHT_60:d->roll_deg=60;break;case SIM_SCENARIO_COMBINED_UP_RIGHT:d->pitch_deg=10;d->roll_deg=30;break;case SIM_SCENARIO_ATTITUDE_FAIL:d->attitude_valid=false;break;case SIM_SCENARIO_ALT_0:d->altitude_ft=0;break;case SIM_SCENARIO_ALT_500:d->altitude_ft=500;break;case SIM_SCENARIO_ALT_1000:d->altitude_ft=1000;break;case SIM_SCENARIO_ALT_2500:case SIM_SCENARIO_ALTITUDE_RECOVERY:d->altitude_ft=2500;break;case SIM_SCENARIO_ALT_5000:d->altitude_ft=5000;break;case SIM_SCENARIO_ALT_9500:d->altitude_ft=9500;break;case SIM_SCENARIO_ALT_10000:d->altitude_ft=10000;break;case SIM_SCENARIO_ALTITUDE_SWEEP:{int p=((int)(s->scenario_t*1000.0f))%10000;d->altitude_ft=p<=5000?p:10000-p;break;}case SIM_SCENARIO_ALTITUDE_FAIL:d->altitude_valid=false;break;case SIM_SCENARIO_HEADING_WRAP:d->heading_deg=wrap_heading(350+(int)(s->scenario_t*2.5f));break;case SIM_SCENARIO_HEADING_FAIL:d->heading_valid=false;break;case SIM_SCENARIO_ALL_FAIL:d->attitude_valid=d->altitude_valid=d->heading_valid=false;break;default:break;}}
